questions.codeSnippet:
p { color: blue; }
.intro { color: green; }
#main p { color: red; }

<p id="main" class="intro">Hello</p>

.box {
  box-sizing: content-box;
  width: 200px;
  padding: 10px;
  border: 5px solid black;
}

a { color: black; }
a:hover { color: orange; }
a.special { color: purple; }
a.special:hover { color: inherit; }

<a href="#" class="special">Link</a>

html { font-size: 20px; }
body { font-size: 0.8em; }
p { font-size: 1.2em; }

<p>Text</p>

p::after {
  content: '';
  display: block;
  width: 50px;
  height: 50px;
  background: red;
}
